import{_ as s,o as e,c as t,a5 as n}from"./chunks/framework.Bt0SrEfo.js";const c=JSON.parse('{"title":"性能优化方法论:Measure → Profile → Optimize → Verify","description":"","frontmatter":{},"headers":[],"relativePath":"performance/21-methodology.md","filePath":"performance/21-methodology.md","lastUpdated":1790177750000}'),r={name:"performance/21-methodology.md"};function o(i,a,l,p,h,d){return e(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="性能优化方法论-measure-→-profile-→-optimize-→-verify" tabindex="-1">性能优化方法论:Measure → Profile → Optimize → Verify <a class="header-anchor" href="#性能优化方法论-measure-→-profile-→-optimize-→-verify" aria-label="Permalink to &quot;性能优化方法论:Measure → Profile → Optimize → Verify&quot;">​</a></h1><h2 id="一、为什么需要方法论" tabindex="-1">一、为什么需要方法论 <a class="header-anchor" href="#一、为什么需要方法论" aria-label="Permalink to &quot;一、为什么需要方法论&quot;">​</a></h2><p>性能优化最容易踩的两个坑:</p><ol><li><strong>凭感觉优化</strong>:&quot;我觉得这慢就优化它&quot;——结果优化错了地方,真正瓶颈没解决</li><li><strong>没有度量就上线</strong>:&quot;我加了个缓存&quot;——结果不知道实际提升多少,可能 0%,也可能引入了 bug</li></ol><p>性能优化是<strong>工程问题</strong>不是艺术问题,需要可重复、可验证、可复盘的方法。</p><h2 id="三、四步法详解" tabindex="-1">三、四步法详解 <a class="header-anchor" href="#三、四步法详解" aria-label="Permalink to &quot;三、四步法详解&quot;">​</a></h2><h4 id="_1-measure-度量-建立基线" tabindex="-1">1. Measure(度量):建立基线 <a class="header-anchor" href="#_1-measure-度量-建立基线" aria-label="Permalink to &quot;1. Measure(度量):建立基线&quot;">​</a></h4><p><strong>目标</strong>:量化&quot;现在有多慢&quot;,作为对比基准。</p><ul><li><strong>真实用户监控(RUM)</strong>:用 Web Vitals 上报 <code>LCP / INP / CLS</code>,聚合真实用户数据</li><li><strong>关键指标</strong>:首屏时间(FCP)、可交互时间(TTI)、总下载字节数、关键 API P99 延迟</li><li><strong>业务指标</strong>:点击转化率、跳出率、用户停留时长</li></ul><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 真实项目:风控平台 v0 阶段指标</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 改造前基线:LCP 4.2s / INP 380ms / CLS 0.18 / 首屏 JS 5.94MB</span></span></code></pre></div><p><strong>没有基线,所有&quot;优化&quot;都是自嗨</strong>。</p><h4 id="_2-profile-定位-找瓶颈" tabindex="-1">2. Profile(定位):找瓶颈 <a class="header-anchor" href="#_2-profile-定位-找瓶颈" aria-label="Permalink to &quot;2. Profile(定位):找瓶颈&quot;">​</a></h4><p><strong>目标</strong>:从&quot;慢&quot;到&quot;哪里慢、为什么慢&quot;。</p><ul><li><strong>Lighthouse</strong>:综合评分 + 优化建议(开发期)</li><li><strong>Chrome DevTools Performance 面板</strong>:火焰图定位长任务、Layout Shift</li><li><strong>Network 面板</strong>:看资源加载瀑布图,识别阻塞请求</li><li><strong>Webpack Bundle Analyzer</strong>:看包体积构成,定位大依赖</li></ul><p>实战经验:<strong>90% 的性能问题集中在 10% 的代码</strong>——一个超大的 ECharts 包、一个未拆分的路由、一个 1MB 的未压缩图片,经常就是全部问题的根源。</p><h4 id="_3-optimize-优化-针对性修复" tabindex="-1">3. Optimize(优化):针对性修复 <a class="header-anchor" href="#_3-optimize-优化-针对性修复" aria-label="Permalink to &quot;3. Optimize(优化):针对性修复&quot;">​</a></h4><p><strong>目标</strong>:只改&quot;瓶颈点&quot;,不要全面铺开。</p><p><strong>优化原则</strong>:</p><ul><li><strong>从大到小</strong>:先解决最大瓶颈(常占 80% 问题)</li><li><strong>少改多收益</strong>:优先改 ROI 高的(几行代码换 50% 提升)</li><li><strong>不改架构优先</strong>:能用 prefetch 解决的不上 SSR,能用 SSR 解决的不重写</li></ul><p><strong>常见瓶颈 → 方案对照表</strong>:</p><table tabindex="0"><thead><tr><th>瓶颈</th><th>优化方案</th></tr></thead><tbody><tr><td>LCP &gt; 2.5s</td><td>关键 CSS 内联 + preload LCP 图片 + SSR</td></tr><tr><td>INP &gt; 200ms</td><td>长任务拆解 + Web Worker + 虚拟列表</td></tr><tr><td>CLS &gt; 0.1</td><td>图片显式宽高 + 字体 font-display: swap + 骨架屏</td></tr><tr><td>JS 体积大</td><td>路由拆包 + 按需引入 + tree-shaking</td></tr><tr><td>接口慢</td><td>GraphQL/聚合接口 + SWR 缓存 + HTTP 缓存</td></tr></tbody></table><h4 id="_4-verify-验证-量化效果" tabindex="-1">4. Verify(验证):量化效果 <a class="header-anchor" href="#_4-verify-验证-量化效果" aria-label="Permalink to &quot;4. Verify(验证):量化效果&quot;">​</a></h4><p><strong>目标</strong>:用数据证明优化有效,<strong>且没有引入回归</strong>。</p><ul><li><strong>A/B 测试</strong>:上线新版本与旧版本对比,看指标变化</li><li><strong>回归测试</strong>:自动化跑 Lighthouse、性能冒烟,集成到 CI</li><li><strong>真实用户验证</strong>:观察上线后 1~2 周 RUM 指标</li></ul><p><strong>实战经验</strong>:<strong>风控平台 Vite 迁移后,Lighthouse 性能分从 41 提升到 92,冷启动从 30s 降到 &lt; 1s,但需要保证功能完整性——所以必须有 Verify 步骤</strong>。</p><h2 id="三、避免的陷阱" tabindex="-1">三、避免的陷阱 <a class="header-anchor" href="#三、避免的陷阱" aria-label="Permalink to &quot;三、避免的陷阱&quot;">​</a></h2><h3 id="_1-早优化" tabindex="-1">1. 早优化 <a class="header-anchor" href="#_1-早优化" aria-label="Permalink to &quot;1. 早优化&quot;">​</a></h3><p>不要在项目刚启动时就考虑&quot;未来 1 万条数据的虚拟列表&quot;——YAGNI 原则,先解决当前 200 条数据的渲染。</p><h3 id="_2-过度优化" tabindex="-1">2. 过度优化 <a class="header-anchor" href="#_2-过度优化" aria-label="Permalink to &quot;2. 过度优化&quot;">​</a></h3><p>JSON.stringify 一个 100 字节的对象,完全不需要;但 10MB JSON 就要考虑 Worker。<strong>看场景,别看&quot;最佳实践&quot;</strong>。</p><h3 id="_3-优化错地方" tabindex="-1">3. 优化错地方 <a class="header-anchor" href="#_3-优化错地方" aria-label="Permalink to &quot;3. 优化错地方&quot;">​</a></h3><p>性能问题 80% 是资源加载或主线程阻塞,很少是&quot;算法不够好&quot;。<strong>先去 Network 面板看加载,再去 Performance 面板看执行</strong>。</p><h3 id="_4-没有监控的优化" tabindex="-1">4. 没有监控的优化 <a class="header-anchor" href="#_4-没有监控的优化" aria-label="Permalink to &quot;4. 没有监控的优化&quot;">​</a></h3><p>没有 RUM 数据,优化就是盲人摸象——你不知道用户真实体验。</p><h2 id="四、实战流程-风控平台-vue2→vite-迁移" tabindex="-1">四、实战流程(风控平台 Vue2→Vite 迁移) <a class="header-anchor" href="#四、实战流程-风控平台-vue2→vite-迁移" aria-label="Permalink to &quot;四、实战流程(风控平台 Vue2→Vite 迁移)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Measure:</span></span>
<span class="line"><span>   - 基线:Lighthouse 41 / 首屏 JS 5.94 MB / 冷启动 30s+</span></span>
<span class="line"><span>   - 用户反馈:&quot;打开慢、转圈、卡&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. Profile:</span></span>
<span class="line"><span>   - Bundle Analyzer 发现:element-plus 全量引入占 1.8 MB</span></span>
<span class="line"><span>   - Network 发现:ECharts 全量引入占 2.4 MB</span></span>
<span class="line"><span>   - Webpack 配置:chunk 拆分不彻底</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. Optimize:</span></span>
<span class="line"><span>   - Vite 替换 Webpack:利用 esbuild 预构建</span></span>
<span class="line"><span>   - element-plus 按需引入</span></span>
<span class="line"><span>   - ECharts 只注册用到的图表</span></span>
<span class="line"><span>   - 路由拆包</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4. Verify:</span></span>
<span class="line"><span>   - Lighthouse 41 → 92</span></span>
<span class="line"><span>   - 首屏 JS 5.94MB → 3.92MB(-34%)</span></span>
<span class="line"><span>   - 冷启动 30s+ → &lt; 1s</span></span>
<span class="line"><span>   - 真实用户首屏时间下降 65%</span></span></code></pre></div><h2 id="五、参考文献" tabindex="-1">五、参考文献 <a class="header-anchor" href="#五、参考文献" aria-label="Permalink to &quot;五、参考文献&quot;">​</a></h2><ul><li><a href="https://web.dev/measure/" target="_blank" rel="noreferrer">web.dev/measure</a></li><li>《高性能网站建设指南》(Steve Souders)</li></ul>`,38)])])}const g=s(r,[["render",o]]);export{c as __pageData,g as default};
